args.code:
on("start", (e) => {
  vars.coins = 0;
  screen.setText("{{hud}}", "message", "Open the chest three times!");
});

on("interact", { asset: "{{chest}}" }, (e) => {
  vars.coins += 1;
  audio.playSound("{{sound}}");
  screen.setText("{{hud}}", "message", "Keep going!");
  if ((vars.coins >= 3)) {
    emit("won");
  }
});

on("custom", { event: "won" }, (e) => {
  once(() => {
    cinematic.play("{{cinematic}}", true);
  });
});

on("cinematicDone", { cinematic: "{{cinematic}}" }, (e) => {
  screen.setText("{{hud}}", "message", "You win!");
});

